REVOKE ALL ON FUNCTION private.employee_reporting_apply(uuid,jsonb,uuid,text) FROM PUBLIC,anon,authenticated,service_role;
SELECT pg_temp.employee_assert_known('disabled');
DO $retained$ BEGIN IF (SELECT data IS DISTINCT FROM pg_temp.employee_retained_data() OR legacy IS DISTINCT FROM pg_temp.employee_catalog(false) FROM employee_recovery_before) THEN RAISE EXCEPTION 'EMPLOYEE_RECOVERY_DATA_OR_LEGACY_CHANGED'; END IF; END $retained$;
COMMIT;
